export interface AsamI18n {
    /** False for an unconfigured legacy tree; formatters preserve their existing defaults. */
    readonly enabled: ComputedRef<boolean>;
    readonly locale: ComputedRef<string>;
    readonly requestedLocale: ComputedRef<string>;
    readonly nativeLocale: ComputedRef<AsamNativeLocale | undefined>;
    readonly issues: ComputedRef<readonly AsamI18nIssue[]>;
    t(...args: AsamI18nCall): string;
    dispose(): void;
}

export type AsamI18nCall = {
    [K in AsamMessageKey]: keyof AsamI18nMessageParameters[K] extends never ? [key: K] : [key: K, values: Readonly<AsamI18nMessageParameters[K]>];
}[AsamMessageKey];

export interface AsamI18nIssue {
    readonly code: 'invalid-config' | 'unsupported-locale' | 'missing-native-locale' | 'missing-message' | 'invalid-message' | 'missing-parameter' | 'native-locale-conflict' | 'disposed';
    readonly locale?: string;
    readonly key?: string;
}

export interface AsamI18nLanguage {
    readonly messages: AsamI18nMessageOverrides;
    readonly nativeLocale?: AsamNativeLocale;
}

export type AsamI18nMessage<P> = string | {
    readonly plural: AsamNumericParameter<P>;
    readonly forms: Readonly<Partial<Record<AsamPluralCategory, string>> & {
        other: string;
    }>;
};

export type AsamI18nMessages = {
    readonly [K in AsamMessageKey]: AsamI18nMessage<AsamI18nMessageParameters[K]>;
};

export interface AsamI18nOptions {
    readonly locale?: AsamLocaleId;
    readonly fallbackLocale?: AsamLocaleId;
    readonly messages?: Readonly<Record<string, AsamI18nMessageOverrides>>;
    readonly languages?: Readonly<Record<string, AsamI18nLanguage>>;
    readonly onIssue?: (issue: AsamI18nIssue) => void;
}

export type AsamNumericParameter<P> = {
    [K in keyof P]: P[K] extends number ? K : never;
}[keyof P];

export interface AsamUiMessageParameters extends AsamU2MessageParameters {
    'ui.common.retry': Record<never, never>;
    'ui.common.loading': Record<never, never>;
    'ui.common.unknown': Record<never, never>;
    'ui.selection.count': {
        count: number;
    };
}

export type AsamUiMessages = {
    readonly [K in keyof AsamUiMessageParameters]: AsamI18nMessage<AsamUiMessageParameters[K]>;
};

