   * @description whether Tooltip is disabled
   */
  disabled?: boolean;
  ariaLabel?: AriaProps['ariaLabel'];
}

interface UseDelayedToggleProps {
  /**
   * @description delay of appearance, in millisecond, not valid in controlled mode
   */
